import SwiftUI

/// The tab bar, the same four tabs as the iOS app's NavBar (Home, Grammar, Library, Settings).
/// Everything under them runs on files shared with the iOS app (DieKarteiCore): the Goethe lists,
/// the SM-2 scheduler, the grammar content, the Hören number engine and the games.
///
/// The icons use iOS's SF Symbol names, filled when selected as in iOS's NavBar. SF Symbols can't
/// ship on Android; the names resolve to Material Symbols / Phosphor symbolsets in
/// Resources/Module.xcassets/Symbols (generated by scripts/android_symbols.py).
enum MenuTab: String, Hashable {
    case home, grammar, library, settings
}

struct ContentView: View {
    /// A new key: the old five-tab bar stored "karten", "spiele", … under "tab".
    @AppStorage("menuTab") var tab = MenuTab.home
    /// Settings ▸ Appearance: "", "light" or "dark".
    @AppStorage("appearance") var appearance = ""

    var colorScheme: ColorScheme? {
        switch appearance {
        case "light": .light
        case "dark": .dark
        default: nil
        }
    }

    var body: some View {
        TabView(selection: $tab) {
            Tab("Home", systemImage: tab == .home ? "house.fill" : "house", value: MenuTab.home) {
                NavigationStack { HomeView(openGrammar: { tab = .grammar }) }
            }
            Tab("Grammar", systemImage: tab == .grammar ? "checklist.checked" : "checklist", value: MenuTab.grammar) {
                NavigationStack { GrammatikView() }
            }
            Tab("Library", systemImage: tab == .library ? "brain.head.profile.fill" : "brain.head.profile", value: MenuTab.library) {
                NavigationStack { LibraryView() }
            }
            Tab("Settings", systemImage: tab == .settings ? "gearshape.2.fill" : "gearshape.2", value: MenuTab.settings) {
                NavigationStack { SettingsView() }
            }
        }
        .preferredColorScheme(colorScheme)
    }
}
